def solve(haystack, needle):
    len_h = len(haystack)
    len_n = len(needle)

    if len_n > len_h:
        return -1

    # Precompute the prefix function for the needle
    def compute_prefix(pattern):
        m = len(pattern)
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and pattern[i] != pattern[j]:
                j = pi[j - 1]
            if pattern[i] == pattern[j]:
                j += 1
            pi[i] = j
        return pi

    prefix = compute_prefix(needle)

    j = 0  # index for needle
    for i in range(len_h):
        while j > 0 and haystack[i] != needle[j]:
            j = prefix[j - 1]
        if haystack[i] == needle[j]:
            j += 1
        if j == len_n:
            return i - len_n + 1
    return -1

