def solve(haystack, needle):
    len_h = len(haystack)
    len_n = len(needle)

    if len_n > len_h:
        return -1

    # Using the Knuth-Morris-Pratt (KMP) algorithm to avoid naive sliding window
    def compute_lps(pattern):
        lps = [0] * len(pattern)
        length = 0  # length of the previous longest prefix suffix

        for i in range(1, len(pattern)):
            while length > 0 and pattern[i] != pattern[length]:
                length = lps[length - 1]
            if pattern[i] == pattern[length]:
                length += 1
                lps[i] = length
            else:
                lps[i] = 0
        return lps

    lps = compute_lps(needle)

    i = j = 0  # i for haystack, j for needle
    while i < len_h:
        if needle[j] == haystack[i]:
            i += 1
            j += 1
        if j == len_n:
            return i - j  # found a match
        elif i < len_h and needle[j] != haystack[i]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1
    return -1

