def solve(intervals):
    if not intervals:
        return []

    # Find the maximum end value to determine the size of the array
    max_end = max(end for start, end in intervals)

    # Initialize a list to track merged intervals
    merged = []

    # Create a list to track if a position is covered
    covered = [False] * (max_end + 1)

    # Mark all positions covered by intervals
    for start, end in intervals:
        for i in range(start, end + 1):
            covered[i] = True

    # Traverse to find merged intervals
    i = 0
    while i <= max_end:
        if covered[i]:
            start = i
            while i <= max_end and covered[i]:
                i += 1
            end = i - 1
            merged.append([start, end])
        else:
            i += 1

    return merged

def solve(intervals):
    if not intervals:
        return []

    # Sort intervals by their start value
    intervals.sort()
    merged = [intervals[0]]

    for current in intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # Overlapping or touching, merge them
            merged[-1][1] = max(last[1], current[1])
        else:
            merged.append(current)

    return merged

