def solve(nums, target):
    def find_first():
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left if left < len(nums) and nums[left] == target else -1

    def find_last():
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] > target:
                right = mid - 1
            else:
                left = mid + 1
        return right if right >= 0 and nums[right] == target else -1

    first = find_first()
    last = find_last()
    return [first, last] if first != -1 else [-1, -1]

